  children: ReactNode;
}

export default function EntityDashboard({
  entityName, listTitle, items, editingId, isProcessing,
  contextHeader, emptyMessage, keyExtractor,
  onClear, onEdit, onDelete, renderItemContent, children
}: EntityDashboardProps) {

  return (



