      <EntityList
        title={listTitle}
        items={items}
        emptyMessage={emptyMessage}
        keyExtractor={keyExtractor}
        isProcessing={isProcessing}
        onEdit={onEdit}
        onDelete={onDelete}
        renderItemContent={renderItemContent}
      />

  );
}

