import { createContext, useContext, useState, useMemo, useCallback, type ReactNode } from 'react';
import { useAdminCases, useAdminPhases, useAdminLevels } from '@/pages/Admin/hooks/useAdminData';
import type { GameCase, Phase, Level } from '@/types';

interface AdminContextState {
  caseId: string;
  phaseId: string;
  levelId: string;
  setCaseId: (id: string) => void;
  setPhaseId: (id: string) => void;
  setLevelId: (id: string) => void;

  cases: GameCase[];
  selectedCase: GameCase | undefined;
  availablePhases: Phase[];
  selectedPhase: Phase | undefined;
  availableLevels: Level[];
  selectedLevel: Level | undefined;

  isLoading: boolean;
  error: Error | null;
}

const AdminContext = createContext(undefined);

export function AdminProvider({ children }: { children: ReactNode }) {
  // Local state for dropdown selections
  const [caseId, setCaseId] = useState('');
  const [phaseId, setPhaseId] = useState('');
  const [levelId, setLevelId] = useState('');

  // Granular Data Fetching
  const { data: cases = [], isLoading: isCasesLoading, error: casesError } = useAdminCases();
  const { data: availablePhases = [], isLoading: isPhasesLoading, error: phasesError } = useAdminPhases(caseId);
  const { data: availableLevels = [], isLoading: isLevelsLoading, error: levelsError } = useAdminLevels(phaseId);

  // Cascading state handlers memoized to maintain stable reference equality
  const handleSetCaseId = useCallback((id: string) => {
    setCaseId(id);
    setPhaseId(''); // Reset child selections when parent changes
    setLevelId('');
  }, []);

  const handleSetPhaseId = useCallback((id: string) => {
    setPhaseId(id);
    setLevelId(''); // Reset child selections when parent changes
  }, []);

  // Derived Data (Memoized to prevent unnecessary recalculations)
  const selectedCase = useMemo(() => cases.find(c => c.id.toString() === caseId), [cases, caseId]);
  const selectedPhase = useMemo(() => availablePhases.find(p => p.id.toString() === phaseId), [availablePhases, phaseId]);
  const selectedLevel = useMemo(() => availableLevels.find(l => l.id.toString() === levelId), [availableLevels, levelId]);

  // Aggregate loading and error states
  const isLoading = isCasesLoading || isPhasesLoading || isLevelsLoading;
  const error = (casesError || phasesError || levelsError) as Error | null;

  // The Provider value is strictly memoized.
  // It will ONLY trigger consumer re-renders when a dependency genuinely updates.
  const value = useMemo(() => ({
    caseId,
    phaseId,
    levelId,
    setCaseId: handleSetCaseId,
    setPhaseId: handleSetPhaseId,
    setLevelId,
    cases,
    selectedCase,
    availablePhases,
    selectedPhase,
    availableLevels,
    selectedLevel,
    isLoading,
    error
  }), [
    caseId,
    phaseId,
    levelId,
    handleSetCaseId,
    handleSetPhaseId,
    cases,
    selectedCase,
    availablePhases,
    selectedPhase,
    availableLevels,
    selectedLevel,
    isLoading,
    error
  ]);

  return {children};
}

export function useAdminContext() {
  const context = useContext(AdminContext);
  if (context === undefined) {
    throw new Error('useAdminContext must be used within an AdminProvider');
  }
  return context;
}

import { useState } from 'react';
import { useAdminCases } from '@/pages/Admin/hooks/useAdminData';
import { useValidatedForm } from '@/pages/Admin/hooks/useValidatedForm';
import { useAdminTranslation } from '@/pages/Admin/hooks/useAdminTranslation';
import EntityDashboard from '@/pages/Admin/components/EntityDashboard';
import { AdminRow, AdminInput, AdminTextarea, AdminCheckbox, AdminFileInput } from '@/pages/Admin/components/AdminUI';
import { validateCaseForm } from '@/pages/Admin/utils/validators';
import type { GameCase } from '@/types';
import './Shared/AdminForms.css';

const initialFormState = {
  title: '', story: '', min_player_XP: '0', XP_on_solve: '100', max_strikes: '5', rating_stars: '5.0',
  age_rating: 'Mature 17+', estimated_playtime: '60 Minutes', difficulty: 'Standard', tags: '',
  author_name: 'System', is_published: false, store_locally: false
};

export default function CaseForm() {
  const { data: cases = [], isLoading: isFetchingCases } = useAdminCases();
  const [image, setImage] = useState(null);
  const { adminT } = useAdminTranslation();
  const t = adminT.forms.caseForm;

  const {
    formData, updateField, editingId, clearForm, handleValidatedSubmit, handleEditInit, handleDelete, registerFileRef, isProcessing
  } = useValidatedForm({
  entityType: 'case',
  initialState: initialFormState,
  validator: validateCaseForm
});

  const onEdit = (c: GameCase) => {
    handleEditInit(c, (caseObj) => ({
      ...initialFormState, ...caseObj,
      tags: Array.isArray(caseObj.tags) ? caseObj.tags.join(', ') : (caseObj.tags || ''),
      is_published: !!caseObj.is_published
    }));
    setImage(null);
  };

  const onClear = () => { clearForm(); setImage(null); };

  return (
    <EntityDashboard
      entityName={t.entityName}
      listTitle={t.manageTitle}
      items={cases}
      editingId={editingId}
      isProcessing={isProcessing}
      isFetching={isFetchingCases}
      emptyMessage={isFetchingCases ? t.loadingArchive : t.noCases}
      keyExtractor={(c) => c.id}
      onClear={onClear}
      onEdit={onEdit}
      onDelete={(c) => handleDelete(c.id, t.deleteConfirm(c.title))}
      renderItemContent={(c) => (
        <>

            [{c.is_published ? t.publishedTag : t.draftTag}]

          ID: {c.id}
          {c.title}
        </>
      )}
    >
       handleValidatedSubmit(e, { image })} className="admin-form">
         updateField('is_published', e.target.checked)} labelTitle={formData.is_published ? t.livePublished : t.draftClassified} description={formData.is_published ? t.liveDescription : t.draftDescription} className={formData.is_published ? 'status-live' : 'status-draft'} />
         updateField('title', e.target.value)} />
         updateField('story', e.target.value)} />


           updateField('min_player_XP', e.target.value)} />
           updateField('XP_on_solve', e.target.value)} />
           updateField('max_strikes', e.target.value)} />



           updateField('difficulty', e.target.value)} />
           updateField('estimated_playtime', e.target.value)} />
           updateField('age_rating', e.target.value)} />



           updateField('rating_stars', e.target.value)} />
           updateField('author_name', e.target.value)} />


         updateField('tags', e.target.value)} />
         setImage(e.target.files?.[0] || null)} />


          {isProcessing ? t.processingData : editingId ? t.updateCase : t.commitCase}



  );
}

import React, { useState } from 'react';
import { useAdminContext } from '@/pages/Admin/context/AdminContext';
import { useValidatedForm } from '@/pages/Admin/hooks/useValidatedForm';
import { useAdminTranslation } from '@/pages/Admin/hooks/useAdminTranslation';
import EntityDashboard from '@/pages/Admin/components/EntityDashboard';
import EvidenceMetadataFields from './Shared/EvidenceMetadataFields';
import { AdminCheckbox, AdminInput, AdminFileInput } from '@/pages/Admin/components/AdminUI';
import { validateEvidenceForm, validateImageSize, validateAudioSize } from '../utils/validators';
import type { Evidence } from '@/types/evidence';
import './Shared/AdminForms.css';

const initialFormState = { title: '', description: '', evidence_type: 'document', sub_type: '', metadata: {} as Record, is_initial: true, is_vital_for_conviction: false, store_locally: false };

export default function EvidenceForm() {
  const { caseId, selectedCase } = useAdminContext();
  const { adminT } = useAdminTranslation();
  const t = adminT.forms.evidenceForm;

  const [image, setImage] = useState(null);
  const [audio, setAudio] = useState(null);

  const {
    formData, setFormData, updateField, editingId, clearForm, handleValidatedSubmit, handleEditInit, handleDelete, registerFileRef, isProcessing
  } = useValidatedForm({
    entityType: 'evidence',
    initialState: initialFormState,
    basePayload: { case_id: caseId },
    validator: validateEvidenceForm
  });

  if (!caseId || !selectedCase) {
    return (



{t.missingContextTitle}
{t.missingContextDesc}

    );
  }

  const handleFileChange = (e: React.ChangeEvent, setFile: React.Dispatch<React.SetStateAction>, validator: (file: File) => string | null) => {
    const file = e.target.files?.[0];
    if (!file) {
      setFile(null);
      return;
    }

    const error = validator(file);
    if (!error) {
      setFile(file);
    } else {
      alert(error);
      setFile(null);
      e.target.value = '';
    }
  };

  const onClear = () => { clearForm(); setImage(null); setAudio(null); };

  const onSubmit = (e: React.FormEvent) => {
    const files: Record = {};
    if ((formData.evidence_type === 'image' || formData.sub_type === 'background_check') && image) files.image = image;
    if (formData.evidence_type === 'audio' && audio) files.audio = audio;
    handleValidatedSubmit(e, files);
  };

  const onEdit = (ev: Evidence | any) => {
    handleEditInit(ev, (e) => ({
      title: e.title, description: e.description || '', evidence_type: e.evidence_type, sub_type: e.sub_type || '', metadata: e.metadata || {}, is_initial: !!e.is_initial, is_vital_for_conviction: !!e.is_vital_for_conviction, store_locally: !!e.store_locally
    }));
    setImage(null); setAudio(null);
  };

  const requiresImage = formData.evidence_type === 'image' || formData.sub_type === 'background_check';
  const requiresLocalToggle = requiresImage || formData.evidence_type === 'audio';

  return (
    <EntityDashboard
      entityName={t.entityName} listTitle={t.manageTitle} items={selectedCase.evidences || []}
      editingId={editingId} isProcessing={isProcessing} emptyMessage={t.emptyMessage}
      contextHeader={t.targetCaseHeader(selectedCase.title)} keyExtractor={(ev) => ev.id.toString()}
      onClear={onClear} onEdit={onEdit} onDelete={(ev) => handleDelete(ev.id, t.deleteConfirm(ev.title))}
      renderItemContent={(ev: any) => (
        <>
          EX-{ev.id.toString().padStart(3, '0')}
          {ev.title}
          {ev.sub_type && {ev.sub_type.replace('_', ' ')}}
        </>
      )}
    >

         updateField('is_initial', e.target.checked)} labelTitle={t.initialEvidenceLabel} description={t.initialEvidenceDesc} className="status-live" />
         updateField('is_vital_for_conviction', e.target.checked)} labelTitle={t.vitalEvidenceLabel} description={t.vitalEvidenceDesc} className="status-draft" />


          {t.masterCategoryLabel}
           setFormData(prev => ({ ...prev, evidence_type: e.target.value, sub_type: '', metadata: {} }))}>
            {t.docOption}{t.testimonyOption}{t.forensicOption}{t.audioOption}{t.imageOption}


         updateField('title', e.target.value)} />
         updateField('description', e.target.value)} />
         updateField('sub_type', val)} metadata={formData.metadata} updateMeta={(key, value) => setFormData(prev => ({ ...prev, metadata: { ...prev.metadata, [key]: value } }))} />
        {requiresImage &&  handleFileChange(e, setImage, validateImageSize)} />}
        {formData.evidence_type === 'audio' &&  handleFileChange(e, setAudio, validateAudioSize)} />}
        {requiresLocalToggle &&  updateField('store_locally', e.target.checked)} labelTitle={t.storeLocallyLabel} className="amber" />}

          {isProcessing ? t.processingData : editingId ? t.updateEvidence : t.commitEvidence}



  );
}

import { useAdminContext } from '@/pages/Admin/context/AdminContext';
import { useValidatedForm } from '@/pages/Admin/hooks/useValidatedForm';
import { useAdminTranslation } from '@/pages/Admin/hooks/useAdminTranslation';
import EntityDashboard from '@/pages/Admin/components/EntityDashboard';
import { getInvestigationRequestLabel } from '@/types';
import type { Evidence, Level, InvestigationRequest } from '@/types';
import { AdminSelect } from '@/pages/Admin/components/AdminUI';
import { validateInvestigationRequestForm } from '@/pages/Admin/utils/validators';
import './Shared/AdminForms.css';

const initialFormState = { request_type: 'search_warrant', required_evidence_ids: [] as string[], unlocks_evidence_id: '', unlocks_level_id: '' };

export default function InvestigationRequestForm() {
  const { caseId, selectedCase } = useAdminContext();
  const { adminT } = useAdminTranslation();
  const t = adminT.forms.investigationRequestForm;

  const {
    formData, updateField, editingId, clearForm, handleValidatedSubmit, handleEditInit, handleDelete, isProcessing
  } = useValidatedForm({
    entityType: 'request',
    initialState: initialFormState,
    basePayload: { case_id: caseId },
    validator: (data) => validateInvestigationRequestForm(
      data,
      t.minTwoEvidenceAlert,
      t.rewardRequiredAlert
    )
  });

  if (!caseId || !selectedCase) {
    return (



{t.missingContextTitle}
{t.missingContextDesc}

    );
  }

  const onEdit = (req: InvestigationRequest) => {
    handleEditInit(req, (r) => ({
      request_type: r.request_type,
      required_evidence_ids: r.required_evidences?.map((ev: Evidence) => ev.id.toString()) || [],
      unlocks_evidence_id: r.unlocks_evidence_id?.toString() || '',
      unlocks_level_id: r.unlocks_level_id?.toString() || ''
    }));
  };

  const allCaseLevels: Level[] = selectedCase.phases?.flatMap(p => p.levels || []) || [];

  return (
    <EntityDashboard
      entityName={t.entityName} listTitle={t.manageTitle} items={selectedCase.investigation_requests || []}
      editingId={editingId} isProcessing={isProcessing} emptyMessage={t.emptyMessage}
      contextHeader={t.targetCaseHeader(selectedCase.title)} keyExtractor={(req) => req.id}
      onClear={clearForm} onEdit={onEdit} onDelete={(req) => handleDelete(req.id, t.deleteConfirm(getInvestigationRequestLabel(req.request_type)))}
      renderItemContent={(req) => (
        <>
          REQ-{req.id}
          {getInvestigationRequestLabel(req.request_type)}


            {t.requiresCount(req.required_evidences?.length || 0)}
            {(req.unlocks_evidence_id || req.unlocks_level_id) && ` ${t.hasReward}`}

        </>
      )}
    >

         updateField('request_type', e.target.value)} options={[
          { value: 'search_warrant', label: getInvestigationRequestLabel('search_warrant') },
          { value: 'financial_subpoena', label: getInvestigationRequestLabel('financial_subpoena') },
          { value: 'toxicology_report', label: getInvestigationRequestLabel('toxicology_report') },
          { value: 'wiretap_authorization', label: getInvestigationRequestLabel('wiretap_authorization') },
          { value: 'ballistics_analysis', label: getInvestigationRequestLabel('ballistics_analysis') },
          { value: 'digital_forensics', label: getInvestigationRequestLabel('digital_forensics') },
          { value: 'exhumation_order', label: getInvestigationRequestLabel('exhumation_order') }
        ]} />



          {t.puzzleHeader}

{t.puzzleHint}
           updateField('required_evidence_ids', Array.from(e.target.selectedOptions, opt => opt.value))}>
            {selectedCase.evidences?.map((ev: Evidence) => (
              EX-{ev.id.toString().padStart(3, '0')} : {ev.title}
            ))}





           updateField('unlocks_evidence_id', e.target.value)} options={[{ value: '', label: t.noEvidenceReward }, ...(selectedCase.evidences?.filter((ev: Evidence) => !ev.is_initial).map((ev: Evidence) => ({ value: ev.id.toString(), label: `EX-${ev.id.toString().padStart(3, '0')} : ${ev.title}` })) || [])]} />
           updateField('unlocks_level_id', e.target.value)} options={[{ value: '', label: t.noLevelReward }, ...allCaseLevels.filter(l => !l.is_initial).map((l: Level) => ({ value: l.id.toString(), label: `Level ${l.order_index} : ${l.title}` }))] } />



