interface CanvasContext {
  levelId: string;
  selectedCase: any;
  selectedPhase: any;
  selectedLevel: any;
  savedNodes: Question[];
}

interface NodeBuilderCanvasProps {
  requiredType: 'interrogation' | 'location' | 'wiretap';
  title: string;
  children: (context: CanvasContext) => ReactNode;
}

export default function NodeBuilderCanvas({ requiredType, title, children }: NodeBuilderCanvasProps) {
  const { levelId, selectedCase, selectedPhase, selectedLevel } = useAdminContext();

  const savedNodes: Question[] = selectedLevel?.questions || [];

  return (







            // {title}


            Targeting: {selectedCase?.title} > {selectedPhase?.title} > {selectedLevel?.title}



        {/* Injecting the context down to the specific mechanic implementation */}
        {children({ levelId, selectedCase, selectedPhase, selectedLevel, savedNodes })}


  );
}

import { useState } from 'react';
import { useAdminContext } from '@/pages/Admin/context/AdminContext';
import { useTargeting } from '@/context/TargetingContext';
import { useAdminTranslation } from '@/pages/Admin/hooks/useAdminTranslation';
import type { Evidence, Level, Phase, Suspect, Victim } from '@/types';
import './ChoiceEditorCard.css';

export interface DraftChoice {
  id?: number | string;
  text: string;
  outcomes?: {
    unlock_evidence?: number[];
    unlock_levels?: number[];
    unlock_suspects?: number[];
    unlock_victims?: number[];
    next_question_id?: number | null;
    gives_strike?: boolean;
    feedback?: string;
  };
  requirements?: {
    required_evidence?: number[];
    required_choices?: number[];
  };
}

export interface LevelWithPhase extends Level {
  phase?: Phase;
  phase_title?: string;
}

export interface FlattenedChoice extends DraftChoice {
  question_id?: number;
  question_text?: string;
}

interface ChoiceEditorCardProps {
  index: number;
  choice: DraftChoice;
  updateChoice: (updated: DraftChoice) => void;
  removeChoice: () => void;
}

export default function ChoiceEditorCard({
  index,
  choice,
  updateChoice,
  removeChoice,
}: ChoiceEditorCardProps) {
  const [isExpanded, setIsExpanded] = useState(
    typeof choice.id === 'string' || choice.id === undefined
  );

  const { selectedCase } = useAdminContext();
  const targeting = useTargeting();
  const { adminT } = useAdminTranslation();
  const t = adminT.forms.choiceEditorCard;

  if (!selectedCase) return null;

  const availableEvidence = selectedCase.evidences || [];
  const availableLevels = selectedCase.phases?.flatMap(p => p.levels || []) || [];
  const availableSuspects = selectedCase.suspects || [];
  const availableVictims = selectedCase.victims || [];

  const updateOutcomes = <K extends keyof NonNullable>(
    key: K,
    value: NonNullable[K]
  ) => {
    updateChoice({ ...choice, outcomes: { ...(choice.outcomes || {}), [key]: value } });
  };

  const updateRequirements = <K extends keyof NonNullable>(
    key: K,
    value: NonNullable[K]
  ) => {
    updateChoice({ ...choice, requirements: { ...(choice.requirements || {}), [key]: value } });
  };

  const unlockedEv = choice.outcomes?.unlock_evidence?.map(String) || [];
  const unlockedLv = choice.outcomes?.unlock_levels?.map(String) || [];
  const unlockedSu = choice.outcomes?.unlock_suspects?.map(String) || [];
  const unlockedVi = choice.outcomes?.unlock_victims?.map(String) || [];
  const reqEv = choice.requirements?.required_evidence?.map(String) || [];

  const hasCoords = choice.text.includes('|') && !choice.text.startsWith('|');
  const coordPreview = hasCoords ? choice.text.split('|')[0].trim() : null;

  const isTargeting = targeting?.activeTarget === choice.id;

  return (


      {/* CLEAN HEADER BAR */}

 setIsExpanded(!isExpanded)}>


          {t.choiceIndex(index + 1)}

            {choice.text ? `"${choice.text}"` : t.blankChoice}


          {coordPreview && (
            📍 {coordPreview}%
          )}

          {choice.outcomes?.gives_strike && (
            {t.strikePenaltyBadge}
          )}



 e.stopPropagation()}>
          {targeting && (
             targeting.toggleTarget(choice.id as string | number)}
            >
              {isTargeting ? t.targetingActive : t.targetingMap}

          )}

           setIsExpanded(!isExpanded)}>
            {isExpanded ? t.collapse : t.expand}



            ✕




      {/* COLLAPSIBLE BODY CONTENT */}
      {isExpanded && (




            {t.choiceTextLabel}
             updateChoice({ ...choice, text: e.target.value })}
              placeholder={t.choiceTextPlaceholder}
            />





{t.narrativeOutcomesTitle}



               updateOutcomes('gives_strike', e.target.checked)}
              />
              {t.penaltyStrikeLabel} {t.penaltyStrikeDesc}




              {t.feedbackLabel}
               updateOutcomes('feedback', e.target.value)}
                placeholder={t.feedbackPlaceholder}
              />






                {t.unlockEvidenceLabel}
                 updateOutcomes('unlock_evidence', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableEvidence.map((ev: Evidence) => (
                    {t.evidenceOption(ev.id, ev.title)}
                  ))}




                {t.unlockLevelsLabel}
                 updateOutcomes('unlock_levels', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableLevels.map((lv: Level) => (
                    {t.levelOption(lv.order_index, lv.title)}
                  ))}








                {t.unlockSuspectsLabel}
                 updateOutcomes('unlock_suspects', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableSuspects.map((su: Suspect) => (
                    {su.name}
                  ))}




                {t.unlockVictimsLabel}
                 updateOutcomes('unlock_victims', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableVictims.map((vi: Victim) => (
                    {vi.name}
                  ))}








{t.gatekeeperRequirementsTitle}


              {t.requiredEvidenceLabel}
               updateRequirements('required_evidence', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                {availableEvidence.map((ev: Evidence) => (
                  {t.evidenceOption(ev.id, ev.title)}
                ))}




      )}

  );
}

import { type ReactNode } from 'react';
import { useAdminTranslation } from '@/pages/Admin/hooks/useAdminTranslation';
import './AdminForms.css';

interface EntityListProps {
  title: string;
  items: T[];
  emptyMessage?: string;
  keyExtractor: (item: T) => string | number;
  renderItemContent: (item: T) => ReactNode;
  onEdit: (item: T) => void;
  onDelete: (item: T) => void;
  isProcessing: boolean;
}

export default function EntityList({
  title,
  items,
  emptyMessage = 'No items found.',
  keyExtractor,
  renderItemContent,
  onEdit,
  onDelete,
  isProcessing
}: EntityListProps) {
  const { adminT } = useAdminTranslation();
  // Fallback safe reference if key isn't added yet, or standard lookup:
  const t = adminT.forms.entityList || { editBtn: 'Edit', deleteBtn: 'Delete' };

  return (




        // {title}


      {items.length === 0 ? (


          {emptyMessage}

      ) : (


          {items.map((item) => (




                {renderItemContent(item)}



                 onEdit(item)}
                  disabled={isProcessing}
                  className="admin-action-btn edit"
                >
                  {t.editBtn}

                 onDelete(item)}
                  disabled={isProcessing}
                  className="admin-action-btn delete"
                >
                  {t.deleteBtn}



          ))}

      )}

  );
}

import { AdminSelect, AdminTextarea } from '@/pages/Admin/components/AdminUI';
import { useAdminTranslation } from '@/pages/Admin/hooks/useAdminTranslation';
import {
  AutopsyFields, BallisticsFields, DNAFields, DigitalForensicsFields, TraceAnalysisFields,
  CorrespondenceFields, FinancialFields, JournalFields, ContractFields, MemoFields, BackgroundCheckFields
} from './MetadataFields';
import './AdminForms.css';

interface EvidenceMetadataFieldsProps {
  evidenceType: string;
  subType: string;
  setSubType: (val: string) => void;
  metadata: Record;
  updateMeta: (key: string, value: any) => void;
}

export default function EvidenceMetadataFields({ evidenceType, subType, setSubType, metadata, updateMeta }: EvidenceMetadataFieldsProps) {
  const { adminT } = useAdminTranslation();
  const t = adminT.forms.evidenceMetadata || {
    sectionTitle: "[ Structured Metadata Injection ]",
    forensicAutopsy: "Autopsy Report",
    forensicBallistics: "Ballistics Analysis",
    forensicDna: "DNA / Serology Profile",
    forensicDigital: "Digital Forensics",
    forensicTrace: "Trace / Material Analysis",
    docCorrespondence: "Correspondence (Email/Letter)",
    docFinancial: "Financial Record",
    docJournal: "Personal Diary / Journal",
    docContract: "Official Contract / Deed",
    docMemo: "Corporate Memo / Note",
    docBackground: "Background Check / Dossier",
    selectForensicPlaceholder: "-- Select Forensic Classification --",
    selectDocPlaceholder: "-- Select Document Classification --",
    officialTranscriptLabel: "Official Transcript"
  };

  const FORENSIC_OPTIONS = [
    { value: "autopsy", label: t.forensicAutopsy },
    { value: "ballistics", label: t.forensicBallistics },
    { value: "dna", label: t.forensicDna },
    { value: "digital_forensics", label: t.forensicDigital },
    { value: "trace_analysis", label: t.forensicTrace }
  ];

  const DOCUMENT_OPTIONS = [
    { value: "correspondence", label: t.docCorrespondence },
    { value: "financial", label: t.docFinancial },
    { value: "journal", label: t.docJournal },
    { value: "contract", label: t.docContract },
    { value: "memo", label: t.docMemo },
    { value: "background_check", label: t.docBackground }
  ];

  const renderSubTypeSelector = () => {
    if (evidenceType === 'forensic') return  setSubType(e.target.value)} options={FORENSIC_OPTIONS} placeholder={t.selectForensicPlaceholder} />;
    if (evidenceType === 'document') return  setSubType(e.target.value)} options={DOCUMENT_OPTIONS} placeholder={t.selectDocPlaceholder} />;
    return null;
  };

  const renderDynamicInputs = () => {
    const props = { metadata, updateMeta: updateMeta as any };

    switch (subType) {
      // FORENSICS
      case 'autopsy': return ;
      case 'ballistics': return ;
      case 'dna': return ;
      case 'digital_forensics': return ;
      case 'trace_analysis': return ;

      // DOCUMENTS
      case 'correspondence': return ;
      case 'financial': return ;
      case 'journal': return ;
      case 'contract': return ;
      case 'memo': return ;
      case 'background_check': return ;

      // FALLBACK
      default:
        if (evidenceType === 'testimony') {
          return  updateMeta('transcript', e.target.value)} />;
        }
        return null;
    }
  };

  if (evidenceType === 'image' || evidenceType === 'audio') return null;

  return (




        {t.sectionTitle}

      {renderSubTypeSelector()}
      {(subType || evidenceType === 'testimony') && (


          {renderDynamicInputs()}

      )}

  );
}

import type { ReactNode } from 'react';
import { useAdminContext } from '@/pages/Admin/context/AdminContext';

interface LevelBuilderGuardProps {
  requiredType: 'location' | 'wiretap' | 'interrogation';
  children: ReactNode;
}

export default function LevelBuilderGuard({ requiredType, children }: LevelBuilderGuardProps) {
  const { caseId, levelId, selectedCase, selectedPhase, selectedLevel } = useAdminContext();

  if (!caseId || !levelId || !selectedCase || !selectedPhase || !selectedLevel) {
    return (




          [ MISSING CONTEXT: TARGET LEVEL REQUIRED ]



          Please select a Case, Phase, and Level from the sidebar to map {requiredType} data.


    );
  }

  if (selectedLevel.presentation_type !== requiredType) {
    return (




          [ INVALID CONTEXT: LEVEL TYPE MISMATCH ]



          The currently selected level is configured for '{selectedLevel.presentation_type}'. You cannot build {requiredType} layouts here. Please select a '{requiredType}' level from the sidebar.


    );
  }

  return <>{children}</>;
}

