export default function BallisticsFields({ metadata, updateMeta }: MetadataFieldProps) {
  const { items, add, update, remove } = useDynamicList<{reference: string, description: string}>(
    metadata.exhibits || [],
    (newList) => updateMeta('exhibits', newList)
  );

  const updateChainOfCustody = (field: string, value: string) => {
    const current = metadata.chain_of_custody || { submitted_by: '', received_date: '' };
    updateMeta('chain_of_custody', { ...current, [field]: value });
  };

  return (
    <>


         updateMeta('case_number', e.target.value)} placeholder="e.g., 2026-BL-8842" />



CHAIN OF CUSTODY

         updateChainOfCustody('submitted_by', e.target.value)} placeholder="e.g., Det. Miller" />
         updateChainOfCustody('received_date', e.target.value)} placeholder="e.g., 2026-06-12" />



BALLISTIC PARAMETERS

         updateMeta('caliber', e.target.value)} placeholder="e.g., 9mm Luger (Winchester)" />
         updateMeta('rifling_pattern', e.target.value)} placeholder="e.g., 6 Lands & Grooves, Right Twist" />


       add({ reference: '', description: '' })} addLabel="+ Add Exhibit" />
      {items.map((ex, idx) => (




             update(idx, 'reference', e.target.value)} placeholder="Ref (e.g. EXHIBIT A)" required />



             update(idx, 'description', e.target.value)} placeholder="Description (e.g. Recovered 9mm Slug)" required />

           remove(idx)} />

      ))}
      {items.length === 0 && 
No exhibits logged. Add a row above.}


TECHNICAL FINDINGS
       updateMeta('firearm_specs', e.target.value)} />
       updateMeta('microscopic_analysis', e.target.value)} />
       updateMeta('trajectory_range', e.target.value)} />
       updateMeta('firing_distance', e.target.value)} placeholder="e.g., Contact to close range (0-30cm)..." />
       updateMeta('conclusion', e.target.value)} placeholder="e.g., MATCH CONFIRMED: Striation patterns on Exhibit A match..." />



        Investigator Handwritten Scrawls
         updateMeta('investigator_notes', e.target.value)} placeholder="Will render in a red cursive marker font..." style={{ minHeight: '80px' }} />

    </>
  );
}

