export interface MetadataFieldProps {
  metadata: Partial;
  updateMeta: (key: K, value: T[K]) => void;
}

import { useQuery } from '@tanstack/react-query';
import { fetchAdminCases, fetchAdminPhases, fetchAdminLevels } from '@/services/adminApi';
import type { GameCase, Phase, Level } from '@/types';

// 1. Fetch Top-Level Cases
export function useAdminCases() {
  return useQuery({
    queryKey: ['adminCases'],
    queryFn: async () => {
      const result = await fetchAdminCases();
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
  });
}

// 2. Fetch Phases (Only triggers when a Case is selected)
export function useAdminPhases(caseId: string) {
  return useQuery({
    queryKey: ['adminPhases', caseId],
    queryFn: async () => {
      const result = await fetchAdminPhases(caseId);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    enabled: !!caseId, // TanStack Query Guard: Prevents execution until caseId exists
  });
}

// 3. Fetch Levels & Nodes (Only triggers when a Phase is selected)
export function useAdminLevels(phaseId: string) {
  return useQuery({
    queryKey: ['adminLevels', phaseId],
    queryFn: async () => {
      const result = await fetchAdminLevels(phaseId);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    enabled: !!phaseId, // TanStack Query Guard: Prevents execution until phaseId exists
  });
}

import React, { useState, useRef } from 'react';
import { useAdminMutations, type AdminEntityType } from '@/pages/Admin/hooks/useAdminMutations';
import { objectToFormData } from '@/pages/Admin/utils/formUtils';

interface UseAdminFormProps {
  entityType: AdminEntityType;
  initialState: T;
  basePayload?: Record;
}

export function useAdminForm<T extends Record>({ entityType, initialState, basePayload = {} }: UseAdminFormProps) {
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState(initialState);

  const fileInputRefs = useRef<Record>({});

  const { createEntity, updateEntity, deleteEntity, isProcessing } = useAdminMutations(entityType);

  const updateField = (field: keyof T, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const clearForm = () => {
    setEditingId(null);
    setFormData(initialState);
    Object.values(fileInputRefs.current).forEach(ref => { if (ref) ref.value = ''; });
  };

  const registerFileRef = (key: string) => (el: HTMLInputElement | null) => {
    fileInputRefs.current[key] = el;
  };

  // STRICT TYPING APPLIED HERE
  const handleSubmit = (e: React.FormEvent, files: Record = {}) => {
    e.preventDefault();

    const payloadData = { ...basePayload, ...formData };
    const payload = objectToFormData(payloadData);

    Object.entries(files).forEach(([key, file]) => {
      if (file) payload.append(key, file);
    });

    if (editingId) {
      updateEntity({ id: editingId, formData: payload }, { onSuccess: clearForm });
    } else {
      createEntity(payload, { onSuccess: clearForm });
    }
  };

  const handleEditInit = (entity: any, mappingFn?: (e: any) => T) => {
    setEditingId(entity.id);
    setFormData(mappingFn ? mappingFn(entity) : { ...initialState, ...entity });

    Object.values(fileInputRefs.current).forEach(ref => { if (ref) ref.value = ''; });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (id: number, warningMessage: string) => {
    if (window.confirm(warningMessage)) {
      if (editingId === id) clearForm();
      deleteEntity(id);
    }
  };

  return {
    formData, setFormData, updateField, editingId, clearForm, handleSubmit,
    handleEditInit, handleDelete, registerFileRef, isProcessing
  };
}

import toast from 'react-hot-toast';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import * as adminApi from '@/services/adminApi';

export type AdminEntityType =
  | 'case'
  | 'phase'
  | 'level'
  | 'question'
  | 'evidence'
  | 'request'
  | 'suspect'
  | 'victim';

export function useAdminMutations(entityType: AdminEntityType) {
  const queryClient = useQueryClient();

  // Map the entity type to the exact API service functions from adminApi
  const apiMap = {
    'case': { create: adminApi.createAdminCase, update: adminApi.updateAdminCase, del: adminApi.deleteAdminCase, name: 'Case' },
    'phase': { create: adminApi.createAdminPhase, update: adminApi.updateAdminPhase, del: adminApi.deleteAdminPhase, name: 'Phase' },
    'level': { create: adminApi.createAdminLevel, update: adminApi.updateAdminLevel, del: adminApi.deleteAdminLevel, name: 'Level' },
    'question': { create: adminApi.createAdminQuestion, update: adminApi.updateAdminQuestion, del: adminApi.deleteAdminQuestion, name: 'Node' },
    'evidence': { create: adminApi.createAdminEvidence, update: adminApi.updateAdminEvidence, del: adminApi.deleteAdminEvidence, name: 'Evidence' },
    'request': { create: adminApi.createAdminInvestigationRequest, update: adminApi.updateAdminInvestigationRequest, del: adminApi.deleteAdminInvestigationRequest, name: 'Request protocol' },
    'suspect': { create: adminApi.createAdminSuspect, update: adminApi.updateAdminSuspect, del: adminApi.deleteAdminSuspect, name: 'Suspect' },
    'victim': { create: adminApi.createAdminVictim, update: adminApi.updateAdminVictim, del: adminApi.deleteAdminVictim, name: 'Victim' },
  };

  const methods = apiMap[entityType];

  const handleSuccess = (action: string) => {
    toast.success(`${methods.name} successfully ${action}.`);
    queryClient.invalidateQueries({ queryKey: ['adminCases'] });
  };

  const handleError = (error: Error) => {
    toast.error(error.message);
  };

  const createMutation = useMutation({
    mutationFn: async (formData: FormData) => {
      const result = await methods.create(formData);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => handleSuccess('created'),
    onError: handleError,
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, formData }: { id: number, formData: FormData }) => {
      const result = await methods.update(id, formData);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => handleSuccess('updated'),
    onError: handleError,
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      const result = await methods.del(id);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => handleSuccess('deleted'),
    onError: handleError,
  });

  const isProcessing = createMutation.isPending || updateMutation.isPending || deleteMutation.isPending;

  return {
    createEntity: createMutation.mutate,
    updateEntity: updateMutation.mutate,
    deleteEntity: deleteMutation.mutate,
    isProcessing
  };
}

import { useTranslation } from 'react-i18next';
import { translations } from '@/locales/ar/translationAdmin';

export type AdminTranslationSchema = typeof translations;

export function useAdminTranslation() {
  const { t } = useTranslation('admin');

  const adminT = buildKeyMap(translations, (path) => t(path)) as AdminTranslationSchema;

  return { adminT };
}

function buildKeyMap(obj: any, tFunc: (path: string) => string, currentPath = ''): any {
  const result: any = {};
  for (const key in obj) {
    const fullPath = currentPath ? `${currentPath}.${key}` : key;
    if (typeof obj[key] === 'object' && obj[key] !== null) {
      result[key] = buildKeyMap(obj[key], tFunc, fullPath);
    } else {
      result[key] = tFunc(fullPath);
    }
  }
  return result;
}

import { useState, useCallback } from 'react';
import type { DraftChoice } from '@/pages/Admin/forms/Shared/ChoiceEditorCard';

export function useCoordinateMapper(
  choices: DraftChoice[],
  setChoices: (choices: DraftChoice[]) => void
) {
  const [activeCoordinateTarget, setActiveCoordinateTarget] = useState(null);

  const handleImageClick = useCallback((e: React.MouseEvent) => {
    if (!activeCoordinateTarget) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const xPercent = (((e.clientX - rect.left) / rect.width) * 100).toFixed(1);
    const yPercent = (((e.clientY - rect.top) / rect.height) * 100).toFixed(1);

    const targetChoice = choices.find(c => c.id === activeCoordinateTarget);
    let title = 'New Point';

    if (targetChoice && targetChoice.text.includes('|')) {
      title = targetChoice.text.split('|')[1].trim();
    } else if (targetChoice && targetChoice.text.trim() !== '') {
      title = targetChoice.text.trim();
    }

    setChoices(choices.map(c =>
      c.id === activeCoordinateTarget
        ? { ...c, text: `${xPercent},${yPercent} | ${title}` }
        : c
    ));

    setActiveCoordinateTarget(null);
  }, [activeCoordinateTarget, choices, setChoices]);

  return {
    activeCoordinateTarget,
    setActiveCoordinateTarget,
    handleImageClick
  };
}

import React, { useState, useRef } from 'react';
import toast from 'react-hot-toast';
import { useAdminContext } from '@/pages/Admin/context/AdminContext';
import { useAdminMutations } from '@/pages/Admin/hooks/useAdminMutations';
import { buildNodeFormData } from '@/pages/Admin/utils/questionUtils';
import type { Question, Choice } from '@/types';
import type { DraftChoice } from '@/pages/Admin/forms/Shared/ChoiceEditorCard';

export function useNodeBuilder(defaultChoices: DraftChoice[] = []) {
  const { setCaseId, setPhaseId, setLevelId, selectedCase, selectedPhase, selectedLevel, levelId } = useAdminContext();

  const [editingId, setEditingId] = useState(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [text, setText] = useState('');
  const [storeLocally, setStoreLocally] = useState(false);
  const [choices, setChoices] = useState(defaultChoices);

  const fileRefs = useRef<Record>({});

  const { createEntity, updateEntity, deleteEntity, isProcessing } = useAdminMutations('question');

  const clearForm = () => {
    setEditingId(null);
    setIsFormOpen(false);
    setText('');
    setStoreLocally(false);
    setChoices(defaultChoices);
    Object.values(fileRefs.current).forEach(ref => { if (ref) ref.value = ''; });
  };

  const registerFileRef = (key: string) => (el: HTMLInputElement | null) => {
    fileRefs.current[key] = el;
  };

  const handleEdit = (node: Question) => {
    // Restore parent context pointers
    if (selectedCase) setCaseId(selectedCase.id.toString());
    if (selectedPhase) setPhaseId(selectedPhase.id.toString());
    if (selectedLevel) setLevelId(selectedLevel.id.toString());

    setIsFormOpen(true);
    setEditingId(node.id);
    setText(node.text || '');
    setStoreLocally(false);

    if (node.choices && node.choices.length > 0) {
      setChoices(node.choices.map((c: Choice) => ({
        id: c.id, text: c.text, requirements: c.requirements || {}, outcomes: c.outcomes || {}
      })));
    } else {
      setChoices(defaultChoices);
    }

    Object.values(fileRefs.current).forEach(ref => { if (ref) ref.value = ''; });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (node: Question) => {
    if (window.confirm('Are you sure you want to delete this asset?')) {
      if (editingId === node.id) clearForm();
      deleteEntity(node.id);
    }
  };

  const handleSubmit = (e: React.FormEvent, files: { image?: File | null, audio?: File | null } = {}) => {
    e.preventDefault();

    if (!text.trim()) { toast.error('Node text cannot be empty.'); return; }
    if (choices.length > 0 && choices.some(c => !c.text.trim())) {
      toast.error('All response branches/choices must have text.'); return;
    }

    const formData = buildNodeFormData({
      level_id: levelId,
      text,
      store_locally: storeLocally,
      choices,
      image: files.image || null,
      audio: files.audio || null,
    });

    if (editingId) {
      updateEntity({ id: editingId, formData }, { onSuccess: clearForm });
    } else {
      createEntity(formData, { onSuccess: clearForm });
    }
  };

  return {
    state: { editingId, isFormOpen, text, storeLocally, choices },
    setters: { setIsFormOpen, setText, setStoreLocally, setChoices },
    actions: { clearForm, handleEdit, handleDelete, handleSubmit, registerFileRef },
    status: { isProcessing }
  };
}

import { useAdminForm } from './useAdminForm';
import toast from 'react-hot-toast';
import type { AdminEntityType } from './useAdminMutations';

interface UseValidatedFormProps {
  entityType: AdminEntityType;
  initialState: T;
  basePayload?: Record;
  validator?: (data: T) => string | null; // Returns error message or null if valid
}

export function useValidatedForm<T extends Record>({
  entityType, initialState, basePayload, validator
}: UseValidatedFormProps) {

  const formManager = useAdminForm({ entityType, initialState, basePayload });

  const handleValidatedSubmit = (
    e: React.FormEvent,
    files?: Record
  ) => {
    e.preventDefault();

    if (validator) {
      const error = validator(formManager.formData);
      if (error) {
        toast.error(error);
        return;
      }
    }

    formManager.handleSubmit(e, files);
  };

  return {
    ...formManager,
    handleValidatedSubmit
  };
}

export const objectToFormData = (obj: Record): FormData => {
  const formData = new FormData();
  Object.entries(obj).forEach(([key, value]) => {
    if (value === null || value === undefined) return;

    if (typeof value === 'boolean') {
      formData.append(key, value ? '1' : '0');
    } else if (typeof value === 'object' && !(value instanceof File) && !(value instanceof Blob)) {
      formData.append(key, JSON.stringify(value));
    } else {
      formData.append(key, value.toString());
    }
  });
  return formData;
};

import type { DraftChoice } from '@/pages/Admin/forms/Shared/ChoiceEditorCard';

export interface ChoiceOutcomes {
  feedback: string;
  next_question_id: number | null;
  gives_strike: boolean;
  unlock_evidence: number[];
  unlock_levels: number[];
  unlock_suspects: number[];
  unlock_victims: number[];
}

export interface ChoiceRequirements {
  required_evidence: number[];
  required_choices: number[];
}

export const defaultRequirements = (): ChoiceRequirements => ({ required_evidence: [], required_choices: [] });

export const defaultOutcomes = (): ChoiceOutcomes => ({
  feedback: '', next_question_id: null, gives_strike: false,
  unlock_evidence: [], unlock_levels: [], unlock_suspects: [], unlock_victims: [],
});

const appendToFormData = (fd: FormData, rootKey: string, obj: any) => {
  if (obj === null || obj === undefined) return;
  if (Array.isArray(obj)) {
      obj.forEach((val, i) => appendToFormData(fd, `${rootKey}[${i}]`, val));
  } else if (typeof obj === 'object' && !(obj instanceof File)) {
      Object.keys(obj).forEach(key => appendToFormData(fd, `${rootKey}[${key}]`, obj[key]));
  } else {
      fd.append(rootKey, obj instanceof File ? obj : obj.toString());
  }
};

export const appendChoicesToFormData = (formData: FormData, choices: any[]) => {
  for (let i = 0; i < choices.length; i++) {
    const choice = choices[i];
    formData.append(`choices[${i}][text]`, choice.text);

    const cleanReqs: any = {};
    if (choice.requirements?.required_evidence?.length > 0) cleanReqs.required_evidence = choice.requirements.required_evidence.map(Number);
    if (choice.requirements?.required_choices?.length > 0) cleanReqs.required_choices = choice.requirements.required_choices.map(Number);
    if (Object.keys(cleanReqs).length > 0) appendToFormData(formData, `choices[${i}][requirements]`, cleanReqs);

    const cleanOutcomes: any = {};
    if (choice.outcomes?.gives_strike) cleanOutcomes.gives_strike = true;
    if (choice.outcomes?.feedback?.trim()) cleanOutcomes.feedback = choice.outcomes.feedback.trim();
    if (choice.outcomes?.next_question_id) cleanOutcomes.next_question_id = Number(choice.outcomes.next_question_id);
    if (choice.outcomes?.unlock_evidence?.length > 0) cleanOutcomes.unlock_evidence = choice.outcomes.unlock_evidence.map(Number);
    if (choice.outcomes?.unlock_levels?.length > 0) cleanOutcomes.unlock_levels = choice.outcomes.unlock_levels.map(Number);
    if (choice.outcomes?.unlock_suspects?.length > 0) cleanOutcomes.unlock_suspects = choice.outcomes.unlock_suspects.map(Number);
    if (choice.outcomes?.unlock_victims?.length > 0) cleanOutcomes.unlock_victims = choice.outcomes.unlock_victims.map(Number);
    if (Object.keys(cleanOutcomes).length > 0) appendToFormData(formData, `choices[${i}][outcomes]`, cleanOutcomes);
  }
};

interface NodePayload {
  level_id: string;
  text: string;
  store_locally: boolean;
  choices: any[];
  image?: File | null;
  audio?: File | null;
}

export const buildNodeFormData = (payload: NodePayload): FormData => {
  const formData = new FormData();
  formData.append('level_id', payload.level_id);
  formData.append('text', payload.text);
  formData.append('store_locally', payload.store_locally ? '1' : '0');

  if (payload.image) formData.append('image', payload.image);
  if (payload.audio) formData.append('audio', payload.audio);

  appendChoicesToFormData(formData, payload.choices);

  return formData;
};

export interface BaseNodeFormProps {
  state: { editingId: number | null; text: string; storeLocally: boolean; choices: DraftChoice[] };
  setters: { setText: (t: string) => void; setStoreLocally: (v: boolean) => void; setChoices: (c: DraftChoice[]) => void };
  actions: { registerFileRef: (key: string) => any; handleSubmit: (e: React.FormEvent) => void; handleCancel: () => void };
  status: { isProcessing: boolean };
  previews: { image?: string | null; audio?: string | null };
}

export const validateCaseForm = (data: { max_strikes: string | number; rating_stars: string | number }) => {
  if (Number(data.max_strikes) < 1) return 'Cases must allow at least 1 strike.';
  if (Number(data.rating_stars) > 5 || Number(data.rating_stars) < 0) return 'Rating must be between 0 and 5.0';
  return null;
};

export const validatePhaseForm = (data: { order_index: string | number }) => {
  if (Number(data.order_index) < 1) return 'Order index must be at least 1.';
  return null;
};

export const validateInvestigationRequestForm = (data: { required_evidence_ids: string[]; unlocks_evidence_id: string; unlocks_level_id: string }, minEvidenceAlert: string, rewardAlert: string) => {
  if (data.required_evidence_ids.length < 2) return minEvidenceAlert;
  if (!data.unlocks_evidence_id && !data.unlocks_level_id) return rewardAlert;
  return null;
};

export const validateLevelForm = (data: { order_index: string | number }) => {
  if (Number(data.order_index) < 1) return 'Order index must be at least 1.';
  return null;
};

export const validateEvidenceForm = (data: { evidence_type: string; sub_type: string }) => {
  if ((data.evidence_type === 'document' || data.evidence_type === 'forensic') && !data.sub_type) {
    return 'You must select a specific classification sub-type for this evidence.';
  }
  return null;
};

export const validateSuspectForm = (data: { name: string }) => {
  if (!data.name.trim()) return 'Suspect name cannot be empty.';
  return null;
};

export const validateVictimForm = (data: { name: string }) => {
  if (!data.name.trim()) return 'Victim name cannot be empty.';
  return null;
};

export const validateImageSize = (file: File | undefined, maxSizeMB: number = 4): string | null => {
  if (!file) return null;
  const MAX_FILE_SIZE = maxSizeMB * 1024 * 1024;
  if (file.size > MAX_FILE_SIZE) {
    const sizeInMB = (file.size / (1024 * 1024)).toFixed(2);
    return `SECURITY WARNING: File size exceeds the ${maxSizeMB}MB limit (Current size: ${sizeInMB}MB). Please compress the image before uploading to prevent UI freezing and HTTP 413 errors.`;
  }
  return null;
};

export const validateAudioSize = (file: File | undefined): string | null => {
  if (!file) return null;
  const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
  if (file.size > MAX_FILE_SIZE) {
    const sizeInMB = (file.size / (1024 * 1024)).toFixed(2);
    return `SECURITY WARNING: File size exceeds the 10MB limit (Current size: ${sizeInMB}MB). Please compress the audio before uploading to prevent UI freezing and HTTP 413 errors.`;
  }
  return null;
};
